        private static Map<String, Keys> keys;
        private final String name;
        private IPropertyKey key;

        private Keys(String name) {
            this.name = name;
        }

        IPropertyKey resolve(IGlobalPropertyService service) {
            if (this.key != null) {
                return this.key;
            }
            if (service == null) {
                return null;
